spi = machine.SPI(
    0,
    baudrate=40000000,  # 40MHz for fast, crisp screen updates
    polarity=1,
    phase=1,
    sck=machine.Pin(18),
    mosi=machine.Pin(19)
)

display = st7789.ST7789(
    spi,
    width,                # Width (Portrait)
    height,              # Height (Portrait)
    reset=HARDWARE.rst,
    dc=HARDWARE.dc,
    cs=HARDWARE.cs,
    rotation=0          # 1 = Landscape (90 deg), 0 = Portrait (0 deg)
)

